/**
 * The target repository of a run: where its tickets build and merge. See #st-build-target.
 *
 * The map, the board, the specs and the ticket files stay in the map's repository. The first
 * --repo given for a subtree is recorded on the board (`run.target`), and every later build,
 * resume, gate and board trigger of that subtree uses it. A different --repo is refused: two
 * targets for one subtree would merge its tickets onto two main lines. With nothing given and
 * nothing recorded, the target is the map's repository.
 */
import { existsSync, realpathSync, statSync } from 'node:fs'
import { resolve } from 'node:path'
import { appendBoard, BOARD_PATH, foldBoard, readBoard } from './board.ts'
import type { Board } from './board.ts'
import { MAIN_LINE, mainLineTip } from './merge.ts'

/** A path as one spelling, so the same directory given two ways compares equal. */
export function canonical(path: string, base: string): string {
  const abs = resolve(base, path)
  return existsSync(abs) ? realpathSync(abs) : abs
}

/** Which repository a run builds in, and whether the choice is new and must be recorded. */
export function chooseTarget(
  b: Board,
  run: string | undefined,
  given: string | undefined,
  mapRepo: string,
): { ok: true; repo: string; record: boolean } | { ok: false; why: string } {
  const recorded = run ? b.runs.get(run)?.target : undefined
  const wanted = given === undefined ? undefined : canonical(given, mapRepo)
  if (recorded && wanted && wanted !== recorded) {
    return { ok: false, why: `${run} builds in ${recorded}, recorded on the board; --repo ${wanted} is a different repository` }
  }
  if (recorded) return { ok: true, repo: recorded, record: false }
  if (wanted) return { ok: true, repo: wanted, record: !!run }
  return { ok: true, repo: canonical(mapRepo, mapRepo), record: false }
}

/**
 * The target of `run`, recorded on the board when it is given for the first time. A given
 * path must be a directory with the main line, checked before it is recorded, so a typo is
 * not kept as the subtree's target.
 */
export async function targetFor(o: {
  run: string | undefined
  given: string | undefined
  mapRepo: string
  boardPath?: string
  mainLine?: string
}): Promise<{ repo: string } | { error: string }> {
  const boardPath = o.boardPath ?? BOARD_PATH
  const c = chooseTarget(foldBoard(readBoard(boardPath)), o.run, o.given, o.mapRepo)
  if (!c.ok) return { error: c.why }
  if (o.given !== undefined && (!existsSync(c.repo) || !statSync(c.repo).isDirectory())) return { error: `--repo ${c.repo} is not a directory` }
  if (c.record) {
    try {
      await mainLineTip(c.repo, o.mainLine ?? MAIN_LINE)
    } catch (e) {
      return { error: `--repo ${c.repo}: ${e instanceof Error ? e.message : String(e)}` }
    }
    appendBoard('run.target', { run: o.run!, repo: c.repo }, { path: boardPath })
  }
  return { repo: c.repo }
}
